apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: {{ $name }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
rules:
  - apiGroups: ["discovery.k8s.io"]
    resources: ["endpointslices"]
    verbs: ["get", "list", "watch"]
---
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: {{ $name }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: Role
  name: {{ $name }}
subjects:
  - kind: ServiceAccount
    name: {{ include "logfire.serviceAccountName" . }}
    namespace: {{ .Release.Namespace }}
{{- if $topology.needsNodeRead }}
{{- /* The zone lookup reads `topology.kubernetes.io/zone` off this pod's node at startup, so it
       needs a cluster-wide read. Opt in with `logfire-ff-bcache.topology.zoneAware`, and make
       sure every zone runs a cache pod: the reader routes to its own zone only. Set
       `logfire-ff-bcache.topology.zone` instead when the cluster will not grant this. */}}
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: {{ $name }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
rules:
  - apiGroups: [""]
    resources: ["nodes"]
    verbs: ["get"]
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRoleBinding
metadata:
  name: {{ $name }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: ClusterRole
  name: {{ $name }}
subjects:
  - kind: ServiceAccount
    name: {{ include "logfire.serviceAccountName" . }}
    namespace: {{ .Release.Namespace }}
{{- end }}

name: Release Charts

on:
  push:
    branches:
      - main
    tags:
      - 'logfire-*'

concurrency:
  group: chart-release
  queue: max
  cancel-in-progress: false

jobs:
  release:
    permissions:
      contents: write
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4
        with:
          fetch-depth: 0
          ref: ${{ github.ref }}

      - name: Detect prerelease
        id: prerelease
        # SemVer prereleases carry a hyphen in the version, e.g. 0.13.24-rc.1.
        # When the chart version is a prerelease, we adjust the GitHub Release flags
        # so the RC does not become "latest".
        run: |
          version=$(sed -nE 's/^version:[[:space:]]*([^[:space:]]+)[[:space:]]*$/\1/p' charts/logfire/Chart.yaml | head -1)
          echo "tag=logfire-${version}" >> "$GITHUB_OUTPUT"
          if [[ -n "$version" && "$version" == *-* ]]; then
            echo "is_prerelease=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_prerelease=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Set up Helm
        uses: azure/setup-helm@v4
        with:
          version: latest

      - name: Configure Git
        run: |
          git config user.name "$GITHUB_ACTOR"
          git config user.email "$GITHUB_ACTOR@users.noreply.github.com"

      - name: Add deps repositories
        run: |
          helm repo add bitnami https://charts.bitnami.com/bitnami
          helm repo add jetstack https://charts.jetstack.io

      - name: Run chart-releaser
        uses: helm/chart-releaser-action@v1.7.0
        env:
          CR_TOKEN: "${{ secrets.GITHUB_TOKEN }}"
        with:
          skip_existing: true
          mark_as_latest: ${{ steps.prerelease.outputs.is_prerelease != 'true' }}

      - name: Flag GitHub release as prerelease
        if: steps.prerelease.outputs.is_prerelease == 'true'
        uses: actions/github-script@v7
        with:
          github-token: "${{ secrets.GITHUB_TOKEN }}"
          script: |
            const tag = '${{ steps.prerelease.outputs.tag }}';
            const { owner, repo } = context.repo;
            try {
              const { data: release } = await github.rest.repos.getReleaseByTag({ owner, repo, tag });
              await github.rest.repos.updateRelease({
                owner,
                repo,
                release_id: release.id,
                prerelease: true,
                make_latest: 'false',
              });
              core.info(`Marked ${tag} as prerelease`);
            } catch (error) {
              if (error?.status === 404) {
                core.info(`No GitHub release found for tag ${tag}; nothing to flag.`);
                return;
              }
              throw error;
            }

      - name: Update release notes from PR body
        uses: actions/github-script@v7
        with:
          github-token: "${{ secrets.GITHUB_TOKEN }}"
          script: |
            const fs = require('fs');

            const chartYaml = fs.readFileSync('charts/logfire/Chart.yaml', 'utf8');
            const versionMatch = chartYaml.match(/^version:\s*([0-9]+\.[0-9]+\.[0-9]+(?:[-+][^\s]+)?)\s*$/m);
            if (!versionMatch) {
              core.info('No chart version found in charts/logfire/Chart.yaml; skipping release notes update.');
              return;
            }

            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const tag = `logfire-${versionMatch[1]}`;
            core.info(`Updating release notes for ${owner}/${repo}@${tag}`);

            let release;
            try {
              ({ data: release } = await github.rest.repos.getReleaseByTag({ owner, repo, tag }));
            } catch (error) {
              if (error?.status === 404) {
                core.info(`No GitHub release found for tag ${tag}; skipping.`);
                return;
              }
              throw error;
            }

            const { data: releaseCommit } = await github.rest.repos.getCommit({ owner, repo, ref: tag });
            const { data: prs } = await github.rest.repos.listPullRequestsAssociatedWithCommit({
              owner,
              repo,
              commit_sha: releaseCommit.sha,
              per_page: 50,
            });

            const pr =
              prs.find((p) => p.merged_at && p.base?.ref === 'main') ||
              prs.find((p) => p.base?.ref === 'main') ||
              prs[0];
            if (!pr) {
              core.info(`No PR associated with commit ${releaseCommit.sha}; skipping release notes update.`);
              return;
            }

            const { data: fullPr } = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: pr.number,
            });

            const prBody = (fullPr.body || '').replace(/\r\n?/g, '\n').trim();
            if (!prBody) {
              core.info(`PR #${pr.number} has no body; skipping release notes update.`);
              return;
            }

            const escapeRegExp = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const extractSection = (body, heading) => {
              const pattern = new RegExp(
                `(?:^|\\n)##\\s+${escapeRegExp(heading)}\\s*(?:\\n|$)([\\s\\S]*?)(?=\\n##\\s+|$)`,
                'i',
              );
              const match = body.match(pattern);
              if (!match) return '';
              return match[1].replace(/<!--[\s\S]*?-->/g, '').trim();
            };

            const summary = extractSection(prBody, 'Summary');
            let upgradeNotes = extractSection(prBody, 'Upgrade notes');
            const breakingChangesLegacy = extractSection(prBody, 'Breaking changes');

            if (!upgradeNotes && breakingChangesLegacy) {
              upgradeNotes = `### Breaking changes\n${breakingChangesLegacy}`;
            } else if (upgradeNotes && breakingChangesLegacy) {
              upgradeNotes = `${upgradeNotes}\n\n### Breaking changes\n${breakingChangesLegacy}`;
            }

            if (!summary && !upgradeNotes) {
              core.info(`PR #${pr.number} does not contain release note sections; skipping release notes update.`);
              return;
            }

            const curated = [];
            if (summary) curated.push('## Summary', summary);
            if (upgradeNotes) curated.push('## Upgrade notes', upgradeNotes);
            curated.push(`PR: ${fullPr.html_url}`);

            const markerStart = '<!-- BEGIN PR NOTES -->';
            const markerEnd = '<!-- END PR NOTES -->';
            const curatedBlock = `${markerStart}\n${curated.join('\n\n')}\n${markerEnd}`;
            const existingBody = (release.body || '').trim();

            let finalBody;
            if (existingBody.includes(markerStart) && existingBody.includes(markerEnd)) {
              finalBody = existingBody.replace(
                new RegExp(`${markerStart}[\\s\\S]*?${markerEnd}`),
                () => curatedBlock,
              );
            } else if (existingBody) {
              finalBody = `${curatedBlock}\n\n---\n\n${existingBody}`;
            } else {
              finalBody = curatedBlock;
            }

            await github.rest.repos.updateRelease({
              owner,
              repo,
              release_id: release.id,
              body: finalBody,
            });

      - name: Update gh-pages README
        # Pre-release commits land on main but the published docs should track the latest
        # stable release — users without --devel are pinned to that, and an RC's README may
        # document features that change or get reverted before the stable bump.
        if: steps.prerelease.outputs.is_prerelease != 'true'
        run: |
          # Store the current README content
          README_CONTENT=$(cat charts/logfire/README.md)

          # Switch to gh-pages branch
          git fetch origin gh-pages
          git checkout gh-pages

          # Update the chart README (this is what GitHub Pages displays)
          echo "$README_CONTENT" > chart/README.md

          # Only commit if there are changes
          if git diff --quiet chart/README.md; then
            echo "No changes to README"
          else
            git add chart/README.md
            git commit -m "Update chart documentation"
            git push origin gh-pages
          fi

{{- $serviceName := "logfire-ff-compaction-worker" }}
{{- $containerSecurityContext := include "logfire.containerSecurityContext" (dict "ctx" . "serviceName" $serviceName) | fromJson }}
{{- $podSecurityContext := include "logfire.fusionfirePodSecurityContext" (dict "ctx" . "serviceName" $serviceName) | fromJson -}}
{{- $effectiveServiceValues := include "logfire.effectiveServiceValues" (dict "Values" .Values "serviceName" $serviceName) | fromJson -}}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ $serviceName }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
    {{- include "logfire.workloadLabels" (dict "Values" .Values "serviceName" $serviceName) | nindent 4 }}
    app.kubernetes.io/component: {{ $serviceName }}
  annotations:
    {{- include "logfire.workloadAnnotations" (dict "Values" .Values "serviceName" $serviceName "secretSources" (list "postgres" "redis")) | nindent 4 }}
spec:
  {{- include "logfire.replicas" (dict "Values" .Values "serviceName" $serviceName) | nindent 2 }}
  revisionHistoryLimit: {{ .Values.revisionHistoryLimit }}
  selector:
    matchLabels:
      {{- include "logfire.selectorLabels" . | nindent 6 }}
      app.kubernetes.io/component: {{ $serviceName }}
  template:
    metadata:
      labels:
        {{- include "logfire.selectorLabels" . | nindent 8 }}
        {{- include "logfire.podLabels" (dict "Values" .Values "serviceName" $serviceName) | nindent 8 }}
        app.kubernetes.io/component: {{ $serviceName }}
      annotations:
        checksum/ff-config: {{ include "logfire.configChecksum" (include (print $.Template.BasePath "/logfire-ff-config.yaml") .) }}
        {{- if or (not .Values.postgresSecret.enabled) (empty .Values.postgresSecret.annotations) }}
        {{- include "logfire.postgresSecretChecksumAnnotation" (dict "ctx" . "key" "postgresFFDsn") | nindent 8 }}
        {{- end }}
        {{- with (include "logfire.redisSecretChecksumAnnotation" (dict "ctx" .) | trim) }}
        {{- . | nindent 8 }}
        {{- end }}
        {{- include "logfire.inClusterTls.server.checksumAnnotation" (dict "ctx" . "serviceName" $serviceName) | nindent 8 }}
        {{- include "logfire.podAnnotations" (dict "Values" .Values "serviceName" $serviceName) | nindent 8 }}
    spec:
      {{- include "logfire.standardPodSpecFields" (dict "ctx" . "serviceName" $serviceName "podSecurityContext" $podSecurityContext) | nindent 6 }}
      containers:
        - name: {{ $serviceName }}
          image: '{{ .Values.image.repository | default "" }}{{ .Values.image.fusionfireImage }}:{{ include "logfire.serviceTag" (dict "Values" .Values "serviceName" $serviceName "Chart" .Chart) }}'
          imagePullPolicy: "{{ .Values.image.pullPolicy }}"
          {{- include "logfire.securityContext" $containerSecurityContext | nindent 10 }}
{{- include "logfire.resources" (dict "Values" .Values "serviceName" $serviceName) | nindent 10 }}
          command:
            {{- include "logfire.ffCommandWithTempDirCleanup" . | nindent 12 }}
          args:
            - compaction-worker
            - --host=0.0.0.0
            - --port=8013
          ports:
            - name: http
              containerPort: 8013
            {{- include "logfire.inClusterTls.https.containerPort" (dict "ctx" .) | nindent 12 }}
          envFrom:
            - configMapRef:
                name: logfire-ff-base-config
            - configMapRef:
                name: logfire-ff-write-config
            - configMapRef:
                name: logfire-ff-maintenance-config
          env:
            {{- include "logfire.ffRedisEnv" . | nindent 12 }}
            {{- include "logfire.ffBackgroundWorkerExecutionEnv" (dict "Values" .Values "serviceName" $serviceName) | nindent 12 }}
            {{- include "logfire.otlpExporterEnv" (dict "root" . "serviceName" $serviceName "codeWorkDir" "/app") | nindent 12 }}
            - name: PG_DSN
              valueFrom:
                secretKeyRef:
                  name: {{ include "logfire.postgresSecretName" . }}
                  key: postgresFFDsn
            {{- include "logfire.objectStoreEnv" . | nindent 12 -}}
            {{- with (index .Values $serviceName | default dict).env }}
              {{- . | toYaml | nindent 12 }}
            {{- end }}
          volumeMounts:
            {{- include "logfire.tmpVolumeMounts" . | nindent 12 }}
            - name: {{ include "logfire.scratchVolumeName" . }}
              mountPath: /scratch
            {{- include "logfire.objectStoreVolumeMounts" . | nindent 12 }}
            {{- include "logfire.inClusterTls.caBundle.volumeMount" (dict "ctx" . "mountPath" "/etc/logfire/incluster-ca") | nindent 12 }}
            {{- include "logfire.inClusterTls.server.volumeMount" (dict "ctx" . "mountPath" "/etc/tls") | nindent 12 }}
          livenessProbe:
            httpGet:
              path: /health
              port: 8013
            initialDelaySeconds: 30
            periodSeconds: 10
            timeoutSeconds: 5
            failureThreshold: 5
          startupProbe:
            {{- include "logfire.ffStartupProbe" (dict "port" 8013) | nindent 12 }}
          readinessProbe:
            {{- include "logfire.ffReadinessProbe" (dict "port" 8013) | nindent 12 }}
      volumes:
      {{- include "logfire.tmpVolume" . | nindent 6 }}
      {{- include "logfire.inClusterTls.caBundle.volume" (dict "ctx" .) | nindent 6 }}
      {{- include "logfire.inClusterTls.server.volume" (dict "ctx" . "serviceName" $serviceName) | nindent 6 }}
      {{- include "logfire.scratchVolume" (dict "root" . "scratchVolume" (get $effectiveServiceValues "scratchVolume" | default dict)) | nindent 6 }}
      {{- include "logfire.objectStoreVolumes" . | nindent 6 }}
{{- template "logfire.autoscaler" (dict "Values" .Values "serviceName" $serviceName) }}
{{- template "logfire.pdb" (dict "root" $ "serviceName" $serviceName) }}

{{- $serviceName := "logfire-backend-auth" }}
{{- $containerSecurityContext := include "logfire.containerSecurityContext" (dict "ctx" . "serviceName" $serviceName) | fromJson }}
{{- $servicePort := 8000 }}
{{- $imageTagOwner := "logfire-backend" }}
{{- if dig "image" "tag" "" (index .Values $serviceName | default dict) }}{{- $imageTagOwner = $serviceName }}{{- end }}
apiVersion: v1
kind: Service
metadata:
  name: {{ $serviceName }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
    app.kubernetes.io/component: {{ $serviceName }}
  annotations:
    {{- include "logfire.serviceAnnotations" (dict "Values" .Values "serviceName" $serviceName) | nindent 4 }}
spec:
  selector:
    {{- include "logfire.selectorLabels" . | nindent 4 }}
    app.kubernetes.io/component: {{ $serviceName }}
  ports:
  - port: {{ $servicePort }}
    targetPort: {{ $servicePort }}
    name: "http"
  {{- include "logfire.inClusterTls.https.servicePort" (dict "ctx" . "targetPort" "https") | nindent 2 }}
  type: ClusterIP
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ $serviceName }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
    {{- include "logfire.workloadLabels" (dict "Values" .Values "serviceName" $serviceName) | nindent 4 }}
    app.kubernetes.io/component: {{ $serviceName }}
  annotations:
    {{- include "logfire.workloadAnnotations" (dict "Values" .Values "serviceName" $serviceName "secretSources" (list "postgres" "existing" "redis")) | nindent 4 }}
spec:
  {{- include "logfire.replicas" (dict "Values" .Values "serviceName" $serviceName) | nindent 2 }}
  revisionHistoryLimit: {{ .Values.revisionHistoryLimit }}
  selector:
    matchLabels:
      {{- include "logfire.selectorLabels" . | nindent 6 }}
      app.kubernetes.io/component: {{ $serviceName }}
  template:
    metadata:
      annotations:
        {{- if or (not .Values.postgresSecret.enabled) (empty .Values.postgresSecret.annotations) }}
        {{- include "logfire.postgresSecretChecksumAnnotation" (dict "ctx" .) | nindent 8 }}
        {{- end }}
        {{- with (include "logfire.redisSecretChecksumAnnotation" (dict "ctx" .) | trim) }}
        {{- . | nindent 8 }}
        {{- end }}
        {{- if or (not .Values.existingSecret.enabled) (empty .Values.existingSecret.annotations) }}
        {{- include "logfire.logfireSecretChecksumAnnotations" (dict "ctx" . "secrets" (list "logfire-jwt-secret")) | nindent 8 }}
        {{- end }}
        {{- include "logfire.podAnnotations" (dict "Values" .Values "serviceName" $serviceName) | nindent 8 }}
      labels:
        {{- include "logfire.selectorLabels" . | nindent 8 }}
        {{- include "logfire.podLabels" (dict "Values" .Values "serviceName" $serviceName) | nindent 8 }}
        app.kubernetes.io/component: {{ $serviceName }}
    spec:
      {{- include "logfire.standardPodSpecFields" (dict "ctx" . "serviceName" $serviceName) | nindent 6 }}
      containers:
        - name: {{ $serviceName }}
          image: '{{ .Values.image.repository | default "" }}{{ .Values.image.backendImage }}:{{ include "logfire.serviceTag" (dict "Values" .Values "serviceName" $imageTagOwner "Chart" .Chart) }}'
          imagePullPolicy: "{{ .Values.image.pullPolicy }}"
          command: ["python", "-m", "logfire_auth.main"]
          {{- include "logfire.securityContext" $containerSecurityContext | nindent 10 }}
          {{- include "logfire.resources" (dict "Values" .Values "serviceName" $serviceName) | nindent 10 }}
          ports:
            - containerPort: {{ $servicePort }}
              protocol: TCP
              name: "http"
            {{- include "logfire.inClusterTls.https.containerPort" (dict "ctx" .) | nindent 12 }}
          startupProbe:
            httpGet:
              path: /health/live
              port: {{ $servicePort }}
            periodSeconds: 5
            timeoutSeconds: 3
            failureThreshold: 12
          livenessProbe:
            httpGet:
              path: /health/live
              port: {{ $servicePort }}
            periodSeconds: 10
            # An overloaded pod answers /health/live slowly but still serves
            # traffic. Restarting it removes capacity and deepens the overload.
            timeoutSeconds: 5
            failureThreshold: 12
          readinessProbe:
            httpGet:
              path: /health
              port: {{ $servicePort }}
            periodSeconds: 10
            timeoutSeconds: 3
            failureThreshold: 3
            successThreshold: 2
          env:
            - name: APP_PORT
              value: {{ $servicePort | quote }}
            - name: LOGFIRE_SERVICE_NAME
              value: {{ $serviceName }}
            - name: LOGFIRE_SERVICE_VERSION
              value: {{ include "logfire.serviceVersion" (dict "root" . "serviceName" $imageTagOwner) | quote }}
            - name: OTEL_RESOURCE_ATTRIBUTES
              value: {{ include "logfire.otelResourceAttributes" (dict "root" . "serviceName" $imageTagOwner "codeWorkDir" "/app") | quote }}
            - name: COLLECTOR_OTLP_GRPC_HOST
              value: http://logfire-otel-collector:4317
            - name: ON_PREM
              value: "true"
            - name: CRUD_PG_DSN
              valueFrom:
                secretKeyRef:
                  name: {{ include "logfire.postgresSecretName" . }}
                  key: postgresDsn
            - name: JWT_SECRET
              valueFrom:
                secretKeyRef:
                  name: {{ include "logfire.externalSecretName" (dict "external" .Values.existingSecret "secretName" "logfire-jwt-secret") }}
                  key: logfire-jwt-secret
            - name: REDIS_DSN
              {{- include "logfire.redisDsnValueFrom" (dict "root" . "key" "sharedDsn") | nindent 14 }}
            - name: SHARED_REDIS_DSN
              {{- include "logfire.redisDsnValueFrom" (dict "root" . "key" "sharedDsn") | nindent 14 }}
            - name: TOKEN_REDIS_DSN
              {{- include "logfire.redisDsnValueFrom" (dict "root" . "key" "tokenDsn") | nindent 14 }}
            - name: TOKEN_REDIS_PREFIX
              value: {{ include "logfire.redisPrefixFor" (dict "root" . "valuesKey" "tokenRedis") | quote }}
            - name: EMAILS_ENABLED
              value: {{ include "logfire.emailsEnabled" . | quote }}
            - name: FRONTEND_HOST
              value: {{ include "logfire.url" . | quote }}
            {{- with (include "logfire.intakeOauthResourceUrl" . | trim) }}
            - name: INTAKE_OAUTH_RESOURCE_URL
              value: {{ . | quote }}
            {{- end }}
            {{- if (index .Values "logfire-ai-gateway" "enabled") }}
            - name: GATEWAY_OAUTH_RESOURCE_URL
              value: {{ include "logfire.gatewayOauthResourceUrl" . | trim | quote }}
            {{- end }}
            {{- include "logfire.rateLimits" . | nindent 12 }}
            {{- if (include "logfire.inClusterTls.enabled" . | eq "true") }}
            - name: LOGFIRE_CA_PATH
              value: /etc/logfire/incluster-ca/ca.crt
            - name: HTTPS_PORT
              value: "{{ .Values.inClusterTls.httpsPort }}"
            - name: TLS_CERT_PATH
              value: "/etc/tls/tls.crt"
            - name: "TLS_KEY_PATH"
              value: "/etc/tls/tls.key"
            {{- end }}
            {{- with (index .Values $serviceName | default dict).env }}
              {{- . | toYaml | nindent 12 }}
            {{- end }}
          volumeMounts:
            {{- include "logfire.tmpVolumeMounts" . | nindent 12 }}
            {{- include "logfire.inClusterTls.caBundle.volumeMount" (dict "ctx" . "mountPath" "/etc/logfire/incluster-ca") | nindent 12 }}
            {{- include "logfire.inClusterTls.server.volumeMount" (dict "ctx" . "mountPath" "/etc/tls") | nindent 12 }}
      volumes:
        {{- include "logfire.tmpVolume" . | nindent 8 }}
        {{- include "logfire.inClusterTls.caBundle.volume" (dict "ctx" .) | nindent 8 }}
        {{- include "logfire.inClusterTls.server.volume" (dict "ctx" . "serviceName" $serviceName) | nindent 8 }}
      terminationGracePeriodSeconds: 30
{{- template "logfire.autoscaler" (dict "Values" .Values "serviceName" $serviceName) }}
{{- template "logfire.pdb" (dict "root" $ "serviceName" $serviceName) }}

{{- $serviceName := "logfire-dex" }}
apiVersion: v1
kind: ServiceAccount
metadata:
  name: {{ $serviceName }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
    app.kubernetes.io/component: {{ $serviceName }}
---
apiVersion: rbac.authorization.k8s.io/v1
kind: Role
metadata:
  name: {{ $serviceName }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
    app.kubernetes.io/component: {{ $serviceName }}
rules:
  - apiGroups: ["dex.coreos.com"]
    resources: ["*"]
    verbs: ["*"]
---
apiVersion: rbac.authorization.k8s.io/v1
kind: RoleBinding
metadata:
  name: {{ $serviceName }}
  labels:
    {{- include "logfire.labels" . | nindent 4 }}
    app.kubernetes.io/component: {{ $serviceName }}
roleRef:
  kind: Role
  apiGroup: rbac.authorization.k8s.io
  name: {{ $serviceName }}
subjects:
- kind: ServiceAccount
  namespace: {{ .Release.Namespace }}
  name: {{ $serviceName }}
